    "evidenceLocations": [
      "Incident command input",
      "Subsystem recovery",
      "Bounded-removal remediation"
    ],
    "observedFailure": "A valid maintenance command accepted an erroneous removal scope and took multiple subsystems below safe capacity.",
    "channel": "authoritative-incident-upstream-fix"
  },
  "publicTaskContract": {
    "publicContract": {
      "goal": "Remove the requested maintenance capacity in accepted batches while keeping every dependent subsystem at or above its declared minimum.",
      "inputGrammar": {
        "notation": "TypeScript",
        "definition": "type RemovalView = { requestId:string, targetCell:string, removeCount:number, maxBatch:number, subsystems:{id:string,current:number,minimum:number,cells:string[]}[] }",
        "validExamples": [
          "{\"requestId\":\"r1\",\"targetCell\":\"c1\",\"removeCount\":2,\"maxBatch\":1,\"subsystems\":[{\"id\":\"index\",\"current\":5,\"minimum\":3,\"cells\":[\"c1\"]}]}"
        ],
        "invalidExamples": [
          "{\"requestId\":\"r1\",\"targetCell\":\"c1\",\"removeCount\":-2,\"subsystems\":[]}"
        ]
      },
      "outputGrammar": {
        "notation": "TypeScript",
        "definition": "type RemovalReport = { status:'COMPLETED'|'REFUSED'|'PARTIAL', acceptedBatches:number[][], removed:number }",
        "validExamples": [
          "{\"status\":\"COMPLETED\",\"acceptedBatches\":[[0],[1]],\"removed\":2}",
          "{\"status\":\"REFUSED\",\"acceptedBatches\":[],\"removed\":0}"
        ],
        "invalidExamples": [
          "{\"status\":\"DONE\",\"removed\":\"all\"}"
        ]
      },
      "stateSemantics": {
        "initialState": "REMOVAL_PLANNED",
        "states": [
          "REMOVAL_PLANNED",
          "BATCH_APPLIED",
          "REMOVAL_COMPLETE",
          "REMOVAL_REFUSED"
        ],
        "transitions": [
          {
            "id": "apply-safe-removal-batch",
            "from": "REMOVAL_PLANNED",
            "input": "Call capacity.remove with at most maxBatch target-cell server indexes.",
            "to": "BATCH_APPLIED",
            "effect": "The harness applies the batch only when every affected subsystem remains at or above minimum."
          },
          {
            "id": "finish-or-refuse-removal",
            "from": "BATCH_APPLIED",
            "input": "Continue with accepted current capacity or stop when the next requested removal would cross a floor.",
            "to": "REMOVAL_COMPLETE",
            "effect": "Report exactly the host-accepted batches and total removals; use PARTIAL when only a prefix is safe."
          }
        ]
      },
      "acceptedOutcomes": [
        "Every batch is no larger than maxBatch, no subsystem falls below minimum, and the report exactly matches accepted host removals."
      ],
      "forbiddenOutcomes": [
        "Crossing any minimum, removing outside targetCell, claiming rejected work, or refusing a wholly safe positive request."
      ],
      "safetyObligations": [
        "Never issue a removal batch that would leave an affected subsystem below its public minimum capacity."
      ],
      "livenessObligations": [
        "Apply at least one batch when the first requested unit is safe and stop only at completion or the first unsafe unit."
      ],
      "implementationFreedom": [
        "The planner may choose any server order and internal data structure when each accepted batch and report obeys the contract."
      ],
      "nonrequirements": [
        "Restart timing, customer traffic, placement algorithms, billing logic, and cross-region recovery are outside this task."
      ]
    },
    "grading": {
      "rules": [
        {
          "id": "capacity-floor-never-crossed",
          "agentVisibleText": "Every accepted batch must leave each affected subsystem current capacity at or above minimum.",
          "publicSection": "Safety floor"
        },
        {
          "id": "capacity-public-batch-limit",
          "agentVisibleText": "No capacity.remove call may contain more than maxBatch server indexes.",
          "publicSection": "Bounded removal"
        },
        {
          "id": "capacity-positive-safe-progress",
          "agentVisibleText": "When one requested removal is safe, at least one accepted removal must occur.",
          "publicSection": "Liveness"
        }
      ],
      "metrics": [
        {
          "id": "capacity-floor-violation-count",
          "unit": "accepted batches crossing a subsystem floor",
          "deterministicProcedure": "Replay host ledger capacities after each accepted batch and count any subsystem with current below minimum.",
          "comparator": "=",
          "threshold": 0,
          "derivation": {
            "formula": "permitted_violation_count",
            "inputs": {
              "permitted_violations": 0
            },
            "explanation": "A hard safety floor permits zero crossings."
          }
        },
        {
          "id": "capacity-oversize-batch-count",
          "unit": "removal calls larger than maxBatch",
          "deterministicProcedure": "Count host-recorded removal calls whose server-index list length exceeds maxBatch.",
          "comparator": "=",
          "threshold": 0,
          "derivation": {
            "formula": "permitted_violation_count",
            "inputs": {
              "permitted_violations": 0
            },
            "explanation": "Every batch is explicitly bounded, so no oversized call is permitted."
          }
        },
        {
          "id": "capacity-safe-removal-count",
          "unit": "host-accepted server removals",
          "deterministicProcedure": "Count accepted removals when the initial fixture proves at least one target server is safe to remove.",
          "comparator": ">=",
          "threshold": 1,
          "derivation": {
            "formula": "minimum_positive_work_count",
            "inputs": {
              "minimum_positive_work": 1
            },
            "explanation": "One accepted unit is the minimum positive progress on a safe request."
          }
        }
      ],
      "checks": [
        {
          "id": "check-capacity-safety-floor",
          "ruleIds": [
            "capacity-floor-never-crossed"
          ],
          "metricIds": [
            "capacity-floor-violation-count"
          ],
          "envelopeDimensionIds": [
            "subsystem-count",
            "headroom-units",
            "dependency-overlap"
          ]
        },
        {
          "id": "check-capacity-batch-bound",
          "ruleIds": [
            "capacity-public-batch-limit"
          ],
          "metricIds": [
            "capacity-oversize-batch-count"
          ],
          "envelopeDimensionIds": [
            "requested-removals",
            "maximum-batch-size"
          ]
        },
        {
          "id": "check-capacity-positive-progress",
          "ruleIds": [
            "capacity-positive-safe-progress"
          ],
          "metricIds": [
            "capacity-safe-removal-count"
          ],
          "envelopeDimensionIds": [
            "headroom-units"
          ]
        }
      ]
    },
    "hiddenInstanceEnvelope": {
      "publicDescription": "Held-out cases vary only subsystem-count, headroom-units, dependency-overlap, requested-removals, maximum-batch-size, all defined below.",
      "dimensions": [
        {
          "id": "subsystem-count",
          "type": "integer",
          "values": [
            1,
            2,
            3
          ],
          "derivation": "The incident crossed multiple dependent subsystems; one is the noninteraction control."
        },
        {
          "id": "headroom-units",
          "type": "integer",
          "values": [
            0,
            1,
            2,
            4
          ],
          "derivation": "Current minus minimum directly determines the safe removal prefix."
        },
        {
          "id": "dependency-overlap",
          "type": "enum",
          "values": [
            "disjoint",
            "partial",
            "shared-target-cell"
          ],
          "derivation": "The source reports one command affecting multiple subsystems through shared servers."
        },
        {
          "id": "requested-removals",
          "type": "integer",
          "values": [
            1,
            2,
            4,
            8
          ],
          "derivation": "Requests straddle the public headroom values to create safe, partial, and refused outcomes."
        },
        {
          "id": "maximum-batch-size",
          "type": "integer",
          "values": [
            1,
            2
          ],
          "derivation": "The remediation requires slower removal; one and two expose one-shot mutants."
        }
      ],
      "samplingProcedure": "Enumerate all floor-boundary cases, then hash-select equal safe, partial, and refused outcomes across overlap classes.",
      "constraints": [
        "Every subsystem minimum is nonnegative and no greater than its initial current capacity.",
        "Server indexes are stable within a case and the facade returns accepted current capacities after every call."
      ],
      "noNewRulesEvidence": "All hidden cases are numeric combinations of the five published dimensions; checks enforce only floor, batch, and progress rules."
    },
    "subjectInterface": {
      "entrypoint": "submission/planner.mjs exports run(view, capacity) returning one RemovalReport.",
      "readableInputs": [
        "RemovalView and capacity.remove(requestId, targetCell, serverIndexes)."
      ],
      "writableOutputs": [
        "Removal calls and one report listing exactly the accepted batch indexes."
      ],
      "unavailableAuthority": [
        "Host capacity ledger, rejected-call ledger, and final subsystem state used by the verifier."
      ]
    },
    "authorityBoundary": {
      "kind": "host-owned live subsystem-capacity ledger",
      "enforcement": "The subject can request removals but cannot edit accepted/rejected records or final capacities outside the capacity facade.",
      "subjectCanCross": false
    },
    "witnessInaccessibility": {
      "witness": "The applied removal sequence and each dependent subsystem's post-batch capacity.",
      "proof": "The facade returns only each call's accepted status and current public counts; the immutable aggregate ledger remains in the parent harness.",
      "locallyObservable": false
    }
  },
